observation.command:
set -e
rm -rf /tmp/pbin && cp -r /workspace/src/Bovis.Web/bin/Debug/net8.0 /tmp/pbin
cd /tmp/pbin
# Confirm the real impl (not ref) assemblies are present
echo "=== presence of key impl dlls in app bin ==="
ls -la Microsoft.Extensions.Configuration.dll Microsoft.Extensions.Configuration.Json.dll Microsoft.Extensions.Configuration.Abstractions.dll Microsoft.Extensions.Configuration.Binder.dll 2>&1 | awk '{print $5, $9}'
cat > probe.csproj <<'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net8.0</TargetFramework>
    <Nullable>disable</Nullable>
    <ImplicitUsings>disable</ImplicitUsings>
    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>
    <AssemblyName>probe</AssemblyName>
  </PropertyGroup>
  <ItemGroup>
    <Compile Include="Program.cs" />
    <Reference Include="Bovis.Web"><HintPath>Bovis.Web.dll</HintPath></Reference>
    <Reference Include="Bovis.Interfaces"><HintPath>Bovis.Interfaces.dll</HintPath></Reference>
    <Reference Include="Microsoft.Extensions.Configuration"><HintPath>Microsoft.Extensions.Configuration.dll</HintPath></Reference>
    <Reference Include="Microsoft.Extensions.Configuration.Json"><HintPath>Microsoft.Extensions.Configuration.Json.dll</HintPath></Reference>
    <Reference Include="Microsoft.Extensions.Configuration.EnvironmentVariables"><HintPath>Microsoft.Extensions.Configuration.EnvironmentVariables.dll</HintPath></Reference>
    <Reference Include="Microsoft.Extensions.Configuration.Binder"><HintPath>Microsoft.Extensions.Configuration.Binder.dll</HintPath></Reference>
    <Reference Include="Microsoft.Extensions.Configuration.Abstractions"><HintPath>Microsoft.Extensions.Configuration.Abstractions.dll</HintPath></Reference>
  </ItemGroup>
</Project>
EOF
cat > Program.cs <<'EOF'
using System;
using System.Reflection;
using Microsoft.Extensions.Configuration;

class Probe {
  static void Main(string[] args) {
    var baseDir = AppContext.BaseDirectory;
    var config = new ConfigurationBuilder()
        .AddJsonFile(baseDir + "appsettings.json", false, true)
        .AddJsonFile(baseDir + "appsettings.Development.json", false, true)
        .AddJsonFile(baseDir + "local.json", false, true)
        .AddEnvironmentVariables()
        .Build();

    var asm = Assembly.LoadFrom(baseDir + "Bovis.Web.dll");
    var ifas = Assembly.LoadFrom(baseDir + "Bovis.Interfaces.dll");
    var binderType = ifas.GetType("Bovis.Interfaces.Configuration.ConfigurableBinder", true);
    binderType.GetConstructor(new Type[]{ typeof(IConfiguration) }).Invoke(new object[]{ config });
    var globals = asm.GetType("Bovis.Web.Globals", true);
    string boundCookie = (string)globals.GetField("AuthCookie", BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);
    string boundPub = (string)globals.GetField("PublicBaseUrl", BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);

    Console.WriteLine("CONFIG[Bovis.Web:AuthCookie]     = " + config["Bovis.Web:AuthCookie"]);
    Console.WriteLine("CONFIG[Bovis.Web:PublicBaseUrl]  = " + config["Bovis.Web:PublicBaseUrl"]);
    Console.WriteLine("BOUND Globals.AuthCookie         = " + boundCookie);
    Console.WriteLine("BOUND Globals.PublicBaseUrl      = " + boundPub);
    Console.WriteLine("COOKIE_MATCH(appsettings==bound) = " + (boundCookie == config["Bovis.Web:AuthCookie"]));
  }
}
EOF
echo "=== build ==="
dotnet build -v q -nologo 2>&1 | tail -3
echo "=== run (env matches server) ==="
ASPNETCORE_ENVIRONMENT=Development dotnet bin/Debug/net8.0/probe.dll 2>&1 | tail -8
